import React, { useState } from 'react';
import DepartmentCard from './components/DepartmentCard';
import ScheduleCalendar from './components/ScheduleCalendar';
import { PlusCircle, LayoutDashboard, Database, ShieldCheck, Printer, AlertTriangle, Zap } from 'lucide-react';

function App() {
  const [departments, setDepartments] = useState([
    { id: 1, name: "College of Computer Studies", code: "CCS" },
    { id: 2, name: "Business Administration", code: "CBA" }
  ]);

  const [globalSchedule, setGlobalSchedule] = useState([]);
  const [allExamDates, setAllExamDates] = useState([]);

  // --- ADD NEW DEPARTMENT ---
  const addDepartment = () => {
    const name = prompt("Enter Department Name:");
    const code = prompt("Enter Department Code (e.g., PSYCH):");
    if (name && code) {
      setDepartments([...departments, { id: Date.now(), name, code: code.toUpperCase() }]);
    }
  };

  // --- CENTRAL SCHEDULING LOGIC ---
  const handleScheduleGenerated = (newAssignments, newDates, deptCode) => {

    // 1. Tag each new session with a unique ID and conflict metadata
    const processedNewData = newAssignments.map(session => {
      // Find any overlap in the REST of the global schedule
      const conflict = globalSchedule.find(existing => 
        existing.dept_code !== deptCode && 
        existing.exam_date === session.exam_date &&
        (existing.room === session.room || existing.proctor === session.proctor) &&
        // TIME OVERLAP MATH: (StartA < EndB) AND (EndA > StartB)
        (session.start_time < existing.end_time && session.end_time > existing.start_time)
      );

      return {
        ...session,
        id: `${deptCode}-${Date.now()}-${Math.random()}`,
        dept_code: deptCode,
        hasConflict: !!conflict,
        conflictWith: conflict ? conflict.dept_code : null,
        conflictType: conflict ? (conflict.room === session.room ? 'ROOM' : 'PROCTOR') : null
      };
    });

    // 2. Atomic Update: Remove old entries for this dept, add the new ones
    setGlobalSchedule(prev => {
      const remainingDepts = prev.filter(item => item.dept_code !== deptCode);
      const updatedList = [...remainingDepts, ...processedNewData];

      // Re-validate EVERYTHING in the list (in case Dept A's change fixed a conflict with Dept B)
      return updatedList.map(item => {
        const otherConflict = updatedList.find(target => 
          target.id !== item.id &&
          target.exam_date === item.exam_date &&
          (target.room === item.room || target.proctor === item.proctor) &&
          (item.start_time < target.end_time && item.end_time > target.start_time)
        );
        return { ...item, hasConflict: !!otherConflict, conflictWith: otherConflict?.dept_code };
      });
    });

    // 3. Update Global Date Registry
    if (newDates && newDates.length > 0) {
      setAllExamDates(prev => {
        const combined = [...new Set([...prev, ...newDates])];
        return combined.filter(d => d).sort((a, b) => new Date(a) - new Date(b));
      });
    }
  };

  const conflictCount = globalSchedule.filter(s => s.hasConflict).length;

  return (
    <div className="min-h-screen bg-slate-50 pb-24 font-sans text-slate-900">
      {/* NAVBAR */}
      <nav className="bg-slate-900 px-8 py-5 mb-10 flex justify-between items-center sticky top-0 z-50 shadow-2xl">
        <div className="flex items-center gap-3">
          <div className="bg-blue-600 p-2 rounded-xl shadow-lg shadow-blue-500/20">
            <LayoutDashboard size={24} className="text-white" />
          </div>
          <div>
            <h1 className="text-xl font-black text-white tracking-tighter leading-none uppercase">
              Exam_Flow <span className="text-blue-500 text-[10px] ml-1">v2.0</span>
            </h1>
            <p className="text-[8px] text-slate-500 font-black tracking-[0.4em] uppercase mt-1">Multi-Dept Conflict Engine</p>
          </div>
        </div>

        <div className="flex items-center gap-6">
            {/* REAL-TIME SYSTEM HEALTH */}
            <div className={`flex items-center gap-3 px-5 py-2.5 rounded-2xl border transition-all ${conflictCount > 0 ? 'bg-rose-500/10 border-rose-500/50' : 'bg-emerald-500/10 border-emerald-500/50'}`}>
                {conflictCount > 0 ? (
                  <>
                    <AlertTriangle size={14} className="text-rose-500 animate-bounce"/>
                    <span className="text-[10px] font-black text-rose-600 uppercase tracking-widest">{conflictCount} Conflicts Active</span>
                  </>
                ) : (
                  <>
                    <ShieldCheck size={14} className="text-emerald-500"/>
                    <span className="text-[10px] font-black text-emerald-600 uppercase tracking-widest">Global Sync Optimal</span>
                  </>
                )}
            </div>
            <button onClick={addDepartment} className="bg-blue-600 hover:bg-blue-500 text-white px-6 py-3 rounded-2xl font-black text-xs uppercase tracking-widest flex items-center gap-2 shadow-xl shadow-blue-900/40 transition-all">
              <PlusCircle size={18} /> New Dept
            </button>
        </div>
      </nav>

      <main className="container mx-auto px-6 max-w-7xl">
        {/* TOP LEVEL STATS */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-12">
            <div className="bg-white p-6 rounded-[2rem] border border-slate-200 shadow-sm">
                <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Active Blocks</p>
                <p className="text-3xl font-black text-slate-900">{globalSchedule.length}</p>
            </div>
            <div className="bg-white p-6 rounded-[2rem] border border-slate-200 shadow-sm">
                <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Departments</p>
                <p className="text-3xl font-black text-slate-900">{departments.length}</p>
            </div>
            <div className="bg-white p-6 rounded-[2rem] border border-slate-200 shadow-sm">
                <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Unique Dates</p>
                <p className="text-3xl font-black text-slate-900">{allExamDates.length}</p>
            </div>
            <div className={`p-6 rounded-[2rem] border-2 shadow-sm ${conflictCount > 0 ? 'bg-rose-50 border-rose-100' : 'bg-emerald-50 border-emerald-100'}`}>
                <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Security Status</p>
                <p className={`text-2xl font-black uppercase ${conflictCount > 0 ? 'text-rose-600' : 'text-emerald-600'}`}>
                  {conflictCount > 0 ? 'Fix Required' : 'Locked'}
                </p>
            </div>
        </div>

        {/* DEPARTMENT INTERFACE LAYER */}
        <div className="space-y-12">
          {departments.map((dept) => (
            <DepartmentCard 
              key={dept.id} 
              deptId={dept.id}
              deptName={dept.name} 
              deptCode={dept.code}
              // THIS IS THE KEY: We pass the WHOLE schedule down
              globalSchedule={globalSchedule}
              onGenerate={(schedule, dates) => handleScheduleGenerated(schedule, dates, dept.code)}
            />
          ))}
        </div>

        {/* MASTER TIMELINE VIEW */}
        <div className="mt-24 pt-24 border-t-2 border-slate-200/60">
            <div className="flex justify-between items-center mb-12">
                <div>
                    <h2 className="text-5xl font-black text-slate-900 tracking-tighter">Master <span className="text-blue-600 italic">Timeline</span></h2>
                    <p className="text-slate-400 font-bold uppercase tracking-[0.3em] text-[10px] mt-2 flex items-center gap-2">
                        <Zap size={12} className="text-amber-500 fill-amber-500"/> Real-time aggregation of all department clusters
                    </p>
                </div>
                <button onClick={() => window.print()} className="bg-slate-900 text-white px-8 py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center gap-3 hover:bg-blue-600 transition-all shadow-2xl">
                    <Printer size={18}/> Export Schedule Report
                </button>
            </div>

            {globalSchedule.length > 0 ? (
                <ScheduleCalendar 
                    scheduleData={globalSchedule} 
                    examDates={allExamDates} 
                />
            ) : (
                <div className="py-32 bg-white rounded-[3rem] border-4 border-dashed border-slate-200 text-center">
                    <p className="text-slate-300 font-black text-xs uppercase tracking-[0.5em]">Waiting for data generation...</p>
                </div>
            )}
        </div>
      </main>

      <footer className="py-20 mt-20 text-center opacity-30">
          <p className="text-[10px] font-black uppercase tracking-[0.5em]">ExamFlow Pro Control System // 2026 Edition</p>
      </footer>
    </div>
  );
}

export default App;
